css:
.wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 80px;
  background: transparent;
}

.machine-container {
  position: relative;
  width: 200px;
  height: 120px;
}

#toggle-input {
  display: none;
}

.box {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 70px;
  background: #2c3e50;
  border-radius: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 5;
  box-shadow: 0 10px 0 #1a252f;
}

.btn {
  width: 120px;
  height: 40px;
  background: #e74c3c;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  color: white;
  font-weight: 900;
  font-family: sans-serif;
  border-bottom: 4px solid #c0392b;
  z-index: 10;
  user-select: none;
  position: relative;
}

.btn-text-on {
  display: none;
}
#toggle-input:checked ~ .box .btn-text-off {
  display: none;
}
#toggle-input:checked ~ .box .btn-text-on {
  display: block;
}

#toggle-input:checked ~ .box .btn {
  background: #2ecc71;
  border-bottom-color: #27ae60;
}

.lid {
  position: absolute;
  top: 40px;
  left: 20px;
  width: 80px;
  height: 8px;
  background: #34495e;
  border-radius: 4px;
  z-index: 4;
  transform-origin: left;
  transition: transform 0.3s ease;
}

#toggle-input:checked ~ .lid {
  transform: rotate(-110deg);
}

.monster {
  position: absolute;
  top: 50px;
  left: 40px;
  width: 60px;
  height: 60px;
  background: #2ecc71;
  border-radius: 25px 25px 5px 5px;
  z-index: 2;
  transition: top 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  display: flex;
  justify-content: center;
  padding-top: 10px;
}

#toggle-input:checked ~ .monster {
  top: -15px;
}

.monster-eye {
  width: 14px;
  height: 14px;
  background: white;
  border-radius: 50%;
  margin: 0 4px;
  position: relative;
  overflow: hidden;
}

.pupil {
  position: absolute;
  width: 6px;
  height: 6px;
  background: black;
  border-radius: 50%;
  left: 4px;
  top: 4px;
  animation: eyeMove 3s infinite alternate;
}

/* Arm Wrapper Logic */
.arm-wrapper {
  position: absolute;
  width: 18px;
  height: 50px;
  left: 105px;
  top: 50px;
  z-index: 20; /* High z-index so it blocks clicks */
  cursor: pointer;
  pointer-events: none; /* Hidden by default */
}

.arm {
  width: 100%;
  height: 100%;
  background: #27ae60;
  border-radius: 10px;
  opacity: 0;
}

#toggle-input:checked ~ .arm-wrapper {
  pointer-events: auto; /* Becomes clickable when checked */
  animation: pushBack 0.6s 0.4s forwards;
}

#toggle-input:checked ~ .arm-wrapper .arm {
  animation: armFade 0.6s 0.4s forwards;
}

@keyframes pushBack {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-65px);
  }
  100% {
    transform: translateY(-65px);
  }
}

@keyframes armFade {
  0% {
    opacity: 0;
  }
  30% {
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    opacity: 1;
  }
}

@keyframes eyeMove {
  0% {
    transform: translate(-2px, 0);
  }
  100% {
    transform: translate(2px, 0);
  }
}
